package com.example.myproject.configuration

import java.util.Properties

/**
 * Build metadata generated by `processResources` from `../app.properties`.
 */
object BuildInfo {
    const val UNKNOWN_VERSION = "unknown"
    private const val RESOURCE = "/build-info.properties"

    val version: String by lazy { readVersion(RESOURCE) }

    internal fun readVersion(resource: String): String {
        val properties = BuildInfo::class.java.getResourceAsStream(resource)
            ?.use { stream -> Properties().apply { load(stream) } }
        return properties?.getProperty("version")
            ?.takeIf { it.isNotBlank() && !it.contains("\${") }
            ?: UNKNOWN_VERSION
    }
}
